import{_ as t,a0 as p,w as o,s as d,I as a,x as e,a1 as n,A as l,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 Ansible 來管理你的工作站：配置自動化 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ansible 來管理你的工作站：配置自動化 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ansible 來管理你的工作站：配置自動化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ansible 來管理你的工作站：配置自動化 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180326 Manage your workstation with Ansible- Automating configuration","title":"使用 Ansible 來管理你的工作站：配置自動化","tag":"201901","desc":""},"relativePath":"201901/20180326 Manage your workstation with Ansible- Automating configuration.md","filePath":"[post].md"}'),r={name:"201901/20180326 Manage your workstation with Ansible- Automating configuration.md"};function u(g,s,b,h,k,m){const i=p("Link");return o(),d("div",null,[s[29]||(s[29]=a("h1",{id:"使用-ansible-來管理你的工作站-配置自動化",tabindex:"-1"},[e("使用 Ansible 來管理你的工作站：配置自動化 "),a("a",{class:"header-anchor",href:"#使用-ansible-來管理你的工作站-配置自動化","aria-label":"Permalink to “使用 Ansible 來管理你的工作站：配置自動化”"},"​")],-1)),s[30]||(s[30]=a("blockquote",null,[a("p",null,"學習如何使 Ansible 自動對一系列台式機和筆記本應用配置。")],-1)),s[31]||(s[31]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/robot_arm_artificial_ai.png?itok=8CUU3U_7",alt:""})],-1)),s[32]||(s[32]=a("p",null,"Ansible 是一個令人驚訝的自動化的配置管理工具。其主要應用在服務器和雲部署上，但在工作站上的應用（無論是台式機還是筆記本）卻鮮少得到關注，這就是本系列所要關注的。",-1)),a("p",null,[s[1]||(s[1]=e("在這個系列的",-1)),n(i,{href:"https://linux.cn/article-10434-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("第一部分",-1)])]),_:1}),s[2]||(s[2]=e("，我向你展示了 ",-1)),s[3]||(s[3]=a("code",null,"ansible-pull",-1)),s[4]||(s[4]=e(" 命令的基本用法，我們創建了一個安裝了少量包的劇本。它本身是沒有多大的用處的，但是為後續的自動化做了準備。",-1))]),a("p",null,[s[6]||(s[6]=e("在這篇文章中，將會達成閉環，而且在最後部分，我們將會有一個針對工作站自動配置的完整的工作解決方案。現在，我們將要設置 Ansible 的配置，這樣未來將要做的改變將會自動的部署應用到我們的工作站上。現階段，假設你已經完成了",-1)),n(i,{href:"https://linux.cn/article-10434-1.html"},{default:l(()=>[...s[5]||(s[5]=[e("第一部分",-1)])]),_:1}),s[7]||(s[7]=e("的工作。如果沒有的話，當你完成的時候回到本文。你應該已經有一個包含第一篇文章中代碼的 GitHub 庫。我們將直接在之前創建的部分之上繼續。",-1))]),s[33]||(s[33]=c(`<p>首先，因為我們要做的不僅僅是安裝包文件，所以我們要做一些重新的組織工作。現在，我們已經有一個名為 <code>local.yml</code> 並包含以下內容的劇本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install packages</span></span>
<span class="line"><span>    apt: name={{item}}</span></span>
<span class="line"><span>    with_items:</span></span>
<span class="line"><span>      - htop</span></span>
<span class="line"><span>      - mc</span></span>
<span class="line"><span>      - tmux</span></span></code></pre></div><p>如果我們僅僅想實現一個任務那麼上面的配置就足夠了。隨着向我們的配置中不斷的添加內容，這個文件將會變的相當的龐大和雜亂。最好能夠根據不同類型的配置將我們的<ruby>動作<rt>play</rt></ruby>分為獨立的文件。為了達到這個要求，創建一個名為<ruby>任務手冊<rt>taskbook</rt></ruby>的東西，它和<ruby>劇本<rt>playbook</rt></ruby>很像但內容更加的流線型。讓我們在 Git 庫中為任務手冊創建一個目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir tasks</span></span></code></pre></div><p><code>local.yml </code> 劇本中的代碼可以很好地過渡為安裝包文件的任務手冊。讓我們把這個文件移動到剛剛創建好的 <code>task</code> 目錄中，並重新命名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv local.yml tasks/packages.yml</span></span></code></pre></div><p>現在，我們編輯 <code>packages.yml</code> 文件將它進行大幅的瘦身，事實上，我們可以精簡除了獨立任務本身之外的所有內容。讓我們把 <code>packages.yml</code> 編輯成如下的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install packages</span></span>
<span class="line"><span>  apt: name={{item}}</span></span>
<span class="line"><span>  with_items:</span></span>
<span class="line"><span>    - htop</span></span>
<span class="line"><span>    - mc</span></span>
<span class="line"><span>    - tmux</span></span></code></pre></div><p>正如你所看到的，它使用同樣的語法，但我們去掉了對這個任務無用沒有必要的所有內容。現在我們有了一個專門安裝包文件的任務手冊。然而我們仍然需要一個名為 <code>local.yml</code> 的文件，因為執行 <code>ansible-pull</code> 命令時仍然會去找這個文件。所以我們將在我們庫的根目錄下（不是在 <code>task</code> 目錄下）創建一個包含這些內容的全新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  pre_tasks:</span></span>
<span class="line"><span>    - name: update repositories</span></span>
<span class="line"><span>      apt: update_cache=yes</span></span>
<span class="line"><span>      changed_when: False</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - include: tasks/packages.yml</span></span></code></pre></div><p>這個新的 <code>local.yml</code> 扮演的是導入我們的任務手冊的索引的角色。我已經在這個文件中添加了一些你在這個系列中還沒見到的內容。首先，在這個文件的開頭處，我添加了 <code>pre_tasks</code>，這個任務的作用是在其他所有任務運行之前先運行某個任務。在這種情況下，我們給 Ansible 的命令是讓它去更新我們的發行版的軟件庫的索引，下面的配置將執行這個任務要求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt: update_cache=yes</span></span></code></pre></div><p>通常 <code>apt</code> 模組是用來安裝包文件的，但我們也能夠讓它來更新軟件庫索引。這樣做的目的是讓我們的每個動作在 Ansible 運行的時候能夠以最新的索引工作。這將確保我們在使用一個老舊的索引安裝一個包的時候不會出現問題。因為 <code>apt</code> 模組僅僅在 Debian、Ubuntu 及它們的衍生發行版下工作。如果你運行的一個不同的發行版，你要使用特定於你的發行版的模組而不是 <code>apt</code>。如果你需要使用一個不同的模組請查看 Ansible 的相關文檔。</p><p>下面這行也需要進一步解釋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>changed_when: False</span></span></code></pre></div><p>在某個任務中的這行阻止了 Ansible 去報告動作改變的結果，即使是它本身在系統中導致的一個改變。在這裏，我們不會去在意庫索引是否包含新的數據；它幾乎總是會的，因為庫總是在改變的。我們不會去在意 <code>apt</code> 庫的改變，因為索引的改變是正常的過程。如果我們刪除這行，我們將在過程報告的後面看到所有的變動，即使僅僅庫的更新而已。最好忽略這類的改變。</p><p>接下來是常規任務的階段，我們將創建好的任務手冊導入。我們每次添加另一個任務手冊的時候，要添加下面這一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tasks:</span></span>
<span class="line"><span>  - include: tasks/packages.yml</span></span></code></pre></div><p>如果你現在運行 <code>ansible-pull</code> 命令，它應該基本上像上一篇文章中做的一樣。不同的是我們已經改進了我們的組織方式，並且能夠更有效的擴展它。為了節省你到上一篇文章中去尋找，<code>ansible-pull</code> 命令的語法參考如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;github_user&gt;/ansible.git</span></span></code></pre></div><p>如果你還記得話，<code>ansible-pull</code> 的命令拉取一個 Git 倉庫並且應用它所包含的配置。</p><p>既然我們的基礎已經搭建好，我們現在可以擴展我們的 Ansible 並且添加功能。更特別的是，我們將添加配置來自動化的部署對工作站要做的改變。為了支撐這個要求，首先我們要創建一個特殊的賬户來應用我們的 Ansible 配置。這個不是必要的，我們仍然能夠在我們自己的用户下運行 Ansible 配置。但是使用一個隔離的用户能夠將其隔離到不需要我們參與的在後台運行的一個系統進程中，</p><p>我們可以使用常規的方式來創建這個用户，但是既然我們正在使用 Ansible，我們應該儘量避開使用手動的改變。替代的是，我們將會創建一個任務手冊來處理用户創建任務。這個任務手冊目前將會僅僅創建一個用户，但你可以在這個任務手冊中添加額外的動作來創建更多的用户。我將這個用户命名為 <code>ansible</code>，你可以按照自己的想法來命名（如果你做了這個改變要確保更新所有出現地方）。讓我們來創建一個名為 <code>user.yml</code> 的任務手冊並且將以下代碼寫進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: create ansible user</span></span>
<span class="line"><span>  user: name=ansible uid=900</span></span></code></pre></div><p>下一步，我們需要編輯 <code>local.yml</code> 文件，將這個新的任務手冊添加進去，像如下這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  pre_tasks:</span></span>
<span class="line"><span>    - name: update repositories</span></span>
<span class="line"><span>      apt: update_cache=yes</span></span>
<span class="line"><span>      changed_when: False</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - include: tasks/users.yml</span></span>
<span class="line"><span>    - include: tasks/packages.yml</span></span></code></pre></div><p>現在當我們運行 <code>ansible-pull</code> 命令的時候，一個名為 <code>ansible</code> 的用户將會在系統中被創建。注意我特地通過參數 <code>uid</code> 為這個用户聲明瞭用户 ID 為 900。這個不是必須的，但建議直接創建好 UID。因為在 1000 以下的 UID 在登錄界面是不會顯示的，這樣是很棒的，因為我們根本沒有需要去使用 <code>ansibe</code> 賬户來登錄我們的桌面。UID 900 是隨便定的；它應該是在 1000 以下沒有被使用的任何一個數值。你可以使用以下命令在系統中去驗證 UID 900 是否已經被使用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/passwd |grep 900</span></span></code></pre></div><p>不過，你使用這個 UID 應該不會遇到什麼問題，因為迄今為止在我使用的任何發行版中我還沒遇到過它是被默認使用的。</p><p>現在，我們已經擁有了一個名為 <code>ansible</code> 的賬户，它將會在之後的自動化配置中使用。接下來，我們可以創建實際的定時作業來自動操作。我們應該將其分開放到它自己的文件中，而不是將其放置到我們剛剛創建的 <code>users.yml</code> 文件中。在任務目錄中創建一個名為 <code>cron.yml</code> 的任務手冊並且將以下的代碼寫進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: install cron job (ansible-pull)</span></span>
<span class="line"><span>  cron: user=&quot;ansible&quot; name=&quot;ansible provision&quot; minute=&quot;*/10&quot; job=&quot;/usr/bin/ansible-pull -o -U https://github.com/&lt;github_user&gt;/ansible.git &gt; /dev/null&quot;</span></span></code></pre></div><p><code>cron</code> 模組的語法幾乎不需加以説明。通過這個動作，我們創建了一個通過用户 <code>ansible</code> 運行的定時作業。這個作業將每隔 10 分鐘執行一次，下面是它將要執行的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/bin/ansible-pull -o -U https://github.com/&lt;github_user&gt;/ansible.git &gt; /dev/null</span></span></code></pre></div><p>同樣，我們也可以添加想要我們的所有工作站部署的額外的定時作業到這個文件中。我們只需要在新的定時作業中添加額外的動作即可。然而，僅僅是添加一個定時的任務手冊是不夠的，我們還需要將它添加到 <code>local.yml</code> 文件中以便它能夠被調用。將下面的一行添加到末尾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- include: tasks/cron.yml</span></span></code></pre></div><p>現在當 <code>ansible-pull</code> 命令執行的時候，它將會以用户 <code>ansible</code> 每隔十分鐘設置一個新的定時作業。但是，每個十分鐘運行一個 Ansible 作業並不是一個好的方式，因為這個將消耗很多的 CPU 資源。每隔十分鐘來運行對於 Ansible 來説是毫無意義的，除非我們已經在 Git 倉庫中改變一些東西。</p><p>然而，我們已經解決了這個問題。注意我在定時作業中的命令 <code>ansible-pill</code> 添加的我們之前從未用到過的參數 <code>-o</code>。這個參數告訴 Ansible 只有在從上次 <code>ansible-pull</code> 被調用以後庫有了變化後才會運行。如果庫沒有任何變化，它將不會做任何事情。通過這個方法，你將不會無端的浪費 CPU 資源。當然在拉取存儲庫的時候會使用一些 CPU 資源，但不會像再一次應用整個配置的時候使用的那麼多。當 <code>ansible-pull</code> 執行的時候，它將會遍歷劇本和任務手冊中的所有任務，但至少它不會毫無目的的運行。</p><p>儘管我們已經添加了所有必須的配置要素來自動化 <code>ansible-pull</code>，它仍然還不能正常的工作。<code>ansible-pull</code> 命令需要 <code>sudo</code> 的權限來運行，這將允許它執行系統級的命令。然而我們創建的用户 <code>ansible</code> 並沒有被設置為以 <code>sudo</code> 的權限來執行命令，因此當定時作業觸發的時候，執行將會失敗。通常我們可以使用命令 <code>visudo</code> 來手動的去設置用户 <code>ansible</code> 去擁有這個權限。然而我們現在應該以 Ansible 的方式來操作，而且這將會是一個向你展示 <code>copy</code> 模組是如何工作的機會。<code>copy</code> 模組允許你從庫複製一個文件到文件系統的任何位置。在這個案列中，我們將會複製 <code>sudo</code> 的一個配置文件到 <code>/etc/sudoers.d/</code> 以便用户 <code>ansible</code> 能夠以管理員的權限執行任務。</p><p>打開 <code>users.yml</code>，將下面的的動作添加到文件末尾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: copy sudoers_ansible</span></span>
<span class="line"><span>  copy: src=files/sudoers_ansible dest=/etc/sudoers.d/ansible owner=root group=root mode=0440</span></span></code></pre></div><p>正如我們看到的，<code>copy</code>模組從我們的倉庫中複製一個文件到其他任何位置。在這個過程中，我們正在抓取一個名為 <code>sudoers_ansible</code>（我們將在後續創建）的文件並將它複製為 <code>/etc/sudoers/ansible</code>，並且擁有者為 <code>root</code>。</p><p>接下來，我們需要創建我們將要複製的文件。在你的倉庫的根目錄下，創建一個名為 <code>files</code> 的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir files</span></span></code></pre></div><p>然後，在我們剛剛創建的 <code>files</code> 目錄裏，創建名為 <code>sudoers_ansible</code> 的文件，包含以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ansible ALL=(ALL) NOPASSWD: ALL</span></span></code></pre></div><p>就像我們正在這樣做的，在 <code>/etc/sudoer.d</code> 目錄裏創建一個文件允許我們為一個特殊的用户配置 <code>sudo</code> 權限。現在我們正在通過 <code>sudo</code> 允許用户 <code>ansible</code> 不需要密碼提示就擁有完全控制權限。這將允許 <code>ansible-pull</code> 以後台任務的形式運行而不需要手動去運行。</p><p>現在，你可以通過再次運行 <code>ansible-pull</code> 來拉取最新的變動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;github_user&gt;/ansible.git</span></span></code></pre></div><p>從這裏開始，<code>ansible-pull</code> 的定時作業將會在後台每隔十分鐘運行一次來檢查你的倉庫是否有變化，如果它發現有變化，將會運行你的劇本並且應用你的任務手冊。</p><p>所以現在我們有了一個完整的可工作方案。當你第一次設置一台新的筆記本或者台式機的時候，你要去手動的運行 <code>ansible-pull</code> 命令，但僅僅是在第一次的時候。從第一次之後，用户 <code>ansible</code> 將會在後台接手後續的運行任務。當你想對你的機器做變動的時候，你只需要簡單的去拉取你的 Git 倉庫來做變動，然後將這些變化回傳到庫中。接着，當定時作業下次在每台機器上運行的時候，它將會拉取變動的部分並應用它們。你現在只需要做一次變動，你的所有工作站將會跟着一起變動。這方法儘管有一點不同尋常，通常，你會有一個包含你的機器列表和不同機器所屬規則的清單文件。然而，<code>ansible-pull</code> 的方法，就像在文章中描述的，是管理工作站配置的非常有效的方法。</p>`,50)),a("p",null,[s[9]||(s[9]=e("我已經在我的 ",-1)),n(i,{href:"https://github.com/jlacroix82/ansible_article.git"},{default:l(()=>[...s[8]||(s[8]=[e("Github 倉庫",-1)])]),_:1}),s[10]||(s[10]=e("中更新了這篇文章中的代碼，所以你可以隨時去瀏覽來對比檢查你的語法。同時我將前一篇文章中的代碼移到了它自己的目錄中。",-1))]),a("p",null,[s[12]||(s[12]=e("在",-1)),n(i,{href:"https://opensource.com/article/18/5/manage-your-workstation-ansible-part-3"},{default:l(()=>[...s[11]||(s[11]=[e("第三部分",-1)])]),_:1}),s[13]||(s[13]=e("，我們將通過介紹使用 Ansible 來配置 GNOME 桌面設置來結束這個系列。我將會告訴你如何設置你的牆紙和鎖屏壁紙、應用一個桌面主題以及更多的東西。",-1))]),s[34]||(s[34]=a("p",null,"同時，到了佈置一些作業的時候了，大多數人都有我們所使用的各種應用的配置文件。可能是 Bash、Vim 或者其他你使用的工具的配置文件。現在你可以嘗試通過我們在使用的 Ansible 庫來自動複製這些配置到你的機器中。在這篇文章中，我已將向你展示瞭如何去複製文件，所以去嘗試以下看看你是都已經能應用這些知識。",-1)),s[35]||(s[35]=a("hr",null,null,-1)),a("p",null,[s[15]||(s[15]=e("via: ",-1)),n(i,{href:"https://opensource.com/article/18/3/manage-your-workstation-configuration-ansible-part-2"},{default:l(()=>[...s[14]||(s[14]=[e("https://opensource.com/article/18/3/manage-your-workstation-configuration-ansible-part-2",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=e("作者：",-1)),n(i,{href:"https://opensource.com/users/jlacroix"},{default:l(()=>[...s[16]||(s[16]=[e("Jay LaCroix",-1)])]),_:1}),s[21]||(s[21]=e(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[17]||(s[17]=[e("lujun9972",-1)])]),_:1}),s[22]||(s[22]=e(" 譯者：",-1)),n(i,{href:"https://github.com/FelixYFZ"},{default:l(()=>[...s[18]||(s[18]=[e("FelixYFZ",-1)])]),_:1}),s[23]||(s[23]=e(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[19]||(s[19]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[24]||(s[24]=[e("LCTT",-1)])]),_:1}),s[27]||(s[27]=e(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...s[25]||(s[25]=[e("Linux中國",-1)])]),_:1}),s[28]||(s[28]=e(" 榮譽推出",-1))])])}const v=t(r,[["render",u]]);export{C as __pageData,v as default};
